(function(){
  'use strict';
  const S=window.OrchardObligations,G=window.OrchardGuidance,M=window.OrchardMeta;
  const refs=[['book',40,'§3, context relative to a responsibility'],['book',50,'§7, currentness and versions'],['book',91,'§19, legitimate reference change']];
  G.registerDefinitions({
    obligationanchor:{title:"Supplied anchor warrant",aliases:["anchor warrant"],plain:"A declared condition saying that the present use has the required supporting warrant. The experiment receives this Boolean premise; it does not authenticate the supporting evidence or create that warrant.",math:"a∈{0,1} is part of the supplied new reference Q₁=¬r₁ ∧ p ∧ a ∧ v. Cases with identical counts and different a can require different eligibility. Authenticating an issuer and establishing a real-world warrant are separate research obligations.",refs},
    obligationcounts:{title:"Supplied count record",aliases:["observed count","capacity"],plain:"In this experiment s is an interpreted observed count, and c is its capacity. Their meanings and the mapping from renamed fields are supplied; the system does not discover what a sensor means.",math:"0≤s≤c. Teaching uses c=3,4; validation c=5; frozen evaluation c=6..9. The installed adapter calls the earlier count interpreter with K=2^c−1 and q=2^s−1, so |K∩q|=s. Equality atoms and Boolean joins retain their supplied meaning.",refs},
    obligationchange:{title:'Change of responsibility',aliases:['change of responsibility','changed obligations'],plain:'A new externally supplied requirement can make yesterday’s answer or context insufficient. A change of the goal must not be counted as better performance against the old goal.',math:'Γ₀ asks r₀(s,c)=1[s=0 or s=c−1]. Γ₁ asks Q₁(x)=1[¬r₁(s,c) ∧ p ∧ a ∧ v], with r₁=1[s=1 or s=c]. Reference authorization is a supplied premise; the learner cannot grant it. The old reference and its result are retained separately.',refs},
    obligationfibre:{title:'Adequacy witness',aliases:['adequacy witness','collision witness'],plain:'Two situations look identical through the current view but require different answers. This identifies the distinction the receiving view is missing.',math:'Exact adequacy: φ(x)=φ(y) ⇒ Q₁(x)=Q₁(y), equivalently Q₁=d∘φ. With φ=(s,c), x=(0,3,1,1,1) and y=(0,3,0,1,1) share a view but need 1 and 0. Search all 32 projections of {s,c,p,a,v} on 120 qualification records; this language has one five-field minimum.',refs},
    obligationtransfer:{title:'Qualified transfer under changing obligations',aliases:['obligation transfer','qualified transfer under changing obligations'],plain:'Reuse the checked OR-pair constructor to build a different response expression, then repair the receiving view and requalify use under the new responsibility.',math:'A replayed stage-five constructor admits 47 candidates. Nine count teaching records at c=3,4 select (s=1) OR (s=c); six separate records at c=5 validate it. Receiving-view qualification uses c=3..5. Freeze before scoring 272 records at c=6..9. Primitive count interpretation and projection search are supplied; no automatic semantic invention is claimed.',refs},
    obligationreceipt:{title:'Version-bound qualification receipt',aliases:['qualification receipt'],plain:'A record binds a checked rule and view to the exact responsibility and revision where they were qualified. Changing the revision makes it stale even if values later return.',math:'Current(ρ)= [ρ.contract=Γ₁] ∧ [ρ.revision=rev] ∧ [ρ.binding=Serialize(Γ₁,rev,g,fields,map)]. Receiving effect additionally requires completed checking and an external current grant. This exact binding assumes an honest host; it is not a digital signature or source authentication.',refs},
    obligationwork:{title:'Later-transfer work',aliases:['later-transfer work'],plain:'A declared ledger charges response fitting, validation, projection testing, mapping checks and historical replay. It is a partial cost model for this later task.',math:'W=|G|·9+6+32·120+34+mapChecks. Valid inherited/preinstalled OR: 4,303; direct AND/OR search: 4,492. Known renaming adds 120 checks. Source acquisition/replay is shown separately (8,394 per pass). Held-out scoring, data construction, encoding, memory and wall time are excluded. This conditional 189-unit difference is not alignment rate dominance.',refs}
  });
  function run(input){
    if(!input||input.protocol!=='orchard-lab/1')throw Error('Unsupported laboratory protocol.');
    const p=input.previous;let artifact=null;
    if(p){if(p.protocol!=='orchard-lab/1'||p.experiment!=='resource-comparison'||!p.passed||p.authorityExpanded!==false)throw Error('Stage seven requires the checked stage-six envelope.');artifact=p.generatorArtifact;}
    const s=S.compare({artifact}),direct=S.compare({route:'direct'}),removed=S.compare({route:'removed',artifact});
    const failures=['bad-feedback','unapproved','off-language','wrong-map'].map(condition=>S.compare({condition,artifact}));
    return {protocol:'orchard-lab/1',experiment:'changing-obligations',passed:s.passed&&s.frozen.wrongAdmissions===0&&s.frozen.warranted===272&&s.legacy.preserved===34&&!removed.passed&&failures.every(r=>!r.passed)&&S.atPhase(s,3,{grant:true,revision:2}).held===272,summary:'Changed rule and release obligations: coarse view has an adequacy witness; learned rule alone warrants 64/272 labels, full requalification 272/272. With fresh supplied grants: 26 correct releases, zero invalid releases. Old-rule shortcut: 190 invalid releases. Later work 4,303 inherited/preinstalled versus 4,492 direct; source replay is separate. Four negative conditions hold. This is a new authored finite study, not a MeRSIA proof.',previousConsumed:!!p,transfer:p?'replayed-constructor-through-resource-stage':'standalone-source-fixture',runtimeEvidenceTransfer:'none',authorityExpanded:false,relativeRateDominanceEstablished:false,study:s,directCost:direct.costs.total,negativeConditions:failures.map(r=>({condition:r.condition,reason:r.reason}))};
  }
  function mount({container}){
    const abort=new AbortController();let study=S.compare(),phase=1,budget=study.costs.total,grant=false,revision=1;
    container.innerHTML=`<section class="intro"><div><div class="chapter">Encounter 07 · When the obligations change</div><h1>Keep the Method. Renew the Qualification.</h1><p>Yesterday’s context answered yesterday’s question. Change the responsibility, learn a different rule, expose the distinctions it needs, and check the path back to use.</p></div><div class="intro-note">Identify the gap.<br>Repair what is missing.<br>Keep authority separate.</div></section>
    <section class="guided-path"><div class="guide-top"><span class="chapter">What this experiment changes</span><span class="helper">A new authored toy inspired by The Aligned Signal §§3, 7 and 19.</span></div><h2>A better rule still needs the right context</h2><p>Here s is the observed count and c is its capacity. The old response marks count 0 or c−1. The new supplied response marks count 1 or c; release now also depends on permission, anchor warrant and source currentness. The inherited OR constructor can build the different response, but a count-only view cannot preserve the new release question.</p><p>The receiver is given interpreted count records. It learns an expression and searches a fixed projection language. The legitimate reference, exact feedback, primitive meanings and permitted repairs are supplied foundations. All actions are simulated.</p></section>
    <div class="workspace"><aside class="controls enquiry-controls"><h2>Set the experiment</h2><label class="field">Construction route<select id="ob-route"><option value="learned">Inherited, replayed OR constructor</option><option value="removed">Remove learned constructor · base 26</option><option value="restored">Restore and replay constructor</option><option value="preinstalled">Strong control · preinstalled OR</option><option value="direct">Direct search · all AND/OR pairs</option></select></label><label class="field">Changed setting<select id="ob-condition"><option value="valid">Authorized new obligations</option><option value="renamed">Known renamed fields · checked mapping</option><option value="bad-feedback">Old answers mislabeled as new teaching</option><option value="unapproved">Reference change lacks authorization</option><option value="off-language">New three-peak rule · outside language</option><option value="wrong-map">Wrong mapping swaps count and capacity</option></select></label><label class="checkbox-line"><input id="ob-grant" type="checkbox">Supply a current simulated receiving grant</label><p class="helper">Starts off. Learning and qualification cannot create permission.</p><button class="secondary wide-button" id="ob-revoke">Withdraw the receiving grant</button><button class="quiet wide-button" id="ob-stale">Change revision after qualification</button><button class="secondary wide-button" id="ob-reset">Reset experiment</button><button class="quiet wide-button" id="ob-glossary">Browse all definitions</button></aside><div>
    <div class="metrics"><div class="metric"><div class="metric-name">New warranted answers</div><div class="metric-value" id="ob-coverage"></div><div class="metric-detail">Frozen 272-case scope</div></div><div class="metric"><div class="metric-name">Invalid releases</div><div class="metric-value" id="ob-unsafe"></div><div class="metric-detail">Current selected phase</div></div><div class="metric"><div class="metric-name">Historical answers retained</div><div class="metric-value" id="ob-history"></div><div class="metric-detail">Old reference stays in the ledger</div></div></div>
    <section class="panel"><h2>Walk through the change of responsibility</h2><div class="obligation-steps" id="ob-steps" role="group" aria-label="Experiment phase"></div><div id="ob-phase-note" class="state-explanation" aria-live="polite"></div><div id="ob-plot"></div><p class="helper">The chart counts answers under the new reference only. Historical prediction and new release eligibility are different questions. The full-test target is 272 answers. The curve shows the completed fixture at each phase; the selected budget may still hold current use. Receiving effects require current-contract qualification, and frozen scoring is separate from acquisition.</p><div id="ob-actions" class="audit-result"></div></section>
    <section class="panel evidence-panel"><h2>The collision that makes context repair necessary</h2><div id="ob-witness" class="obligation-witness"></div><p>Same count, different answer. The adequacy witness is computed over the qualification scope, not inferred from how long a prompt is. Within these five coordinate fields, the exact search finds a unique minimum: all five are needed for this release question.</p><div id="ob-view" class="obligation-fields"></div></section>
    <section class="panel evidence-panel"><h2>Can the inherited method really build a different repair?</h2><div id="ob-rule"></div><label class="field">Later-transfer work budget <strong id="ob-budget-label"></strong><input id="ob-budget" type="range" min="0" max="6000" step="1" value="4303" style="width:100%;margin-top:14px"></label><div id="ob-costs" class="table-wrap"></div><p id="ob-source-cost" class="helper"></p><p>The nine teaching records use c=3,4. Six separate response-validation records use c=5. View qualification tests all 32 coordinate projections on 120 records at c=3..5. The repaired pipeline is then frozen and scored at c=6..9. Fixtures were inspected during development; this is internal verification, not independent replication.</p><p>Preinstalled OR matches inheritance on the later task. Direct search also succeeds. The inherited method narrows one declared candidate search by 189 prediction units; source learning/replay and the supplied adapter remain real costs. This is not a comparison with every possible optimized baseline.</p></section></div></div>
    <section class="panel evidence-panel"><h2>Stress boundaries that do not disappear with more permission</h2><div id="ob-boundaries" class="table-wrap"></div><p>A three-peak target exceeds the one-pair language. Wrong teaching fails separate validation. A swapped field mapping fails the supplied correspondence check. Missing authorization leaves the proposed new reference unadopted. The framework can identify these failures here because those contracts and checks have been supplied.</p><p>The qualification receipt binds the actual revision. Changing it holds use; returning the same field values cannot erase that intervening revision. Equality assumes an honest local host and does not authenticate an issuer or protect against hostile code.</p><p><a href="downloads/07_changing_obligations_source.html" target="_blank" rel="noopener">Inspect the self-contained Python experiment</a> · <a href="downloads/07_changing_obligations.py" download>Download .py</a> · <a href="downloads/07_changing_obligations_report.html">Computed report</a> · <a href="vision.html">Why this direction matters →</a></p></section>`;
    const q=id=>container.querySelector('#'+id),on=(id,event,fn)=>q(id).addEventListener(event,fn,{signal:abort.signal});
    const boundaries=['valid','renamed','bad-feedback','unapproved','off-language','wrong-map'].map(condition=>S.compare({condition}));
    q('ob-boundaries').innerHTML=`<table class="inspector-table"><thead><tr><th>Condition</th><th>Computed result</th><th>Boundary</th></tr></thead><tbody>${boundaries.map(r=>`<tr><td>${r.condition}</td><td>${r.passed?'Qualified':'Hold'}</td><td>${r.reason}</td></tr>`).join('')}</tbody></table>`;
    function render(){
      const r=S.atPhase(study,phase,{grant,budget,revision});q('ob-coverage').textContent=r.warranted+'/272';q('ob-unsafe').textContent=r.wrongAdmissions;q('ob-history').textContent=study.legacy.preserved+'/'+study.legacy.predictions;
      q('ob-steps').innerHTML=study.phases.map((p,i)=>`<button type="button" data-ob-phase="${i}" aria-pressed="${phase===i}">${i+1}. ${p.name}</button>`).join('');q('ob-phase-note').textContent=study.phases[phase].explanation+' Current gate: '+r.reason+'.';
      const sx=i=>55+100*i,sy=n=>170-130*n/272;
      q('ob-plot').innerHTML=`<svg class="frontier-svg" viewBox="0 0 420 255" role="img" aria-label="New-contract warranted answers by phase: ${study.phases.map(p=>p.newWarranted).join(', ')} out of 272. Current phase ${phase+1}."><title>Warranted answers under the changed obligations</title><line x1="45" y1="40" x2="365" y2="40" stroke="#087859" stroke-dasharray="5 4"/><text x="45" y="26">Frozen-test target / ceiling: 272 answers</text><line x1="45" y1="170" x2="365" y2="170" stroke="#ccd7e1"/><text x="12" y="174">0</text><text x="8" y="45">272</text><polyline points="${study.phases.map((p,i)=>sx(i)+','+sy(p.newWarranted)).join(' ')}" fill="none" stroke="#2359af" stroke-width="3"/>${study.phases.map((p,i)=>`<circle cx="${sx(i)}" cy="${sy(p.newWarranted)}" r="${i===phase?7:4}" fill="${i===phase?'#087859':'#2359af'}"/><text x="${sx(i)}" y="${sy(p.newWarranted)-12}" text-anchor="middle">${p.newWarranted}</text><text x="${sx(i)}" y="198" text-anchor="middle">Phase ${i+1}</text>`).join('')}<text x="45" y="226">Horizontal: declared change / repair phase</text><text x="45" y="245">Vertical: warranted new-contract answers</text></svg>`;
      q('ob-actions').textContent='Simulated effects: '+r.admissions+' releases, '+r.blocks+' blocks, '+r.held+' held. '+(grant?'A current grant is supplied.':'The receiving grant is off.')+' Unchecked old-rule shortcut would release '+study.unchecked.admissions+' cases, including '+study.unchecked.wrongAdmissions+' that violate the new contract.';
      const w=study.projection.coarse.witness;q('ob-witness').innerHTML=[w.left,w.right].map((x,i)=>`<article><span>Case ${i+1} · same visible (s,c)</span><strong>(${x.s}, ${x.c}) → ${i===0?w.leftAnswer:w.rightAnswer}</strong><p>Permission ${x.permission} · anchor ${x.anchor} · current ${x.current}</p></article>`).join('');
      q('ob-view').innerHTML=S.FIELDS.map(f=>`<span class="${phase===3?'exposed':!['s','c'].includes(f)?'missing':''}">${f==='s'?'observed count (s)':f==='c'?'capacity (c)':f==='anchor'?'anchor warrant (a)':f}${phase<3&&!['s','c'].includes(f)?' · hidden':''}</span>`).join('');
      q('ob-rule').textContent='Candidate space: '+study.candidates+'. Selected expression: '+(study.expressionLabel||'none')+'. Status: '+study.reason+'.';q('ob-budget-label').textContent=budget.toLocaleString();
      const direct=S.compare({route:'direct',condition:study.condition}),pre=S.compare({route:'preinstalled',condition:study.condition});
      q('ob-costs').innerHTML=`<table class="inspector-table"><thead><tr><th>Declared phase</th><th>Selected route</th><th>Preinstalled OR</th><th>Direct AND/OR</th></tr></thead><tbody>${[['Fit predictions','fit'],['Response validation','validation'],['Projection record visits','projection'],['Descriptor mapping checks','mapping'],['Historical checks','legacy'],['Later-work total','total']].map(([label,k])=>`<tr><td>${label}</td><td>${study.costs[k].toLocaleString()}</td><td>${pre.costs[k].toLocaleString()}</td><td>${direct.costs[k].toLocaleString()}</td></tr>`).join('')}</tbody></table>`;
      q('ob-source-cost').textContent='Selected source acquisition/replay: '+study.sourceCommonWork.toLocaleString()+' declared units, shown separately from the later-task budget. Source costs are zero for the supplied preinstalled/direct controls. Frozen scoring, data generation, serialization, memory and elapsed time are excluded.';
      G.annotate(container);
    }
    function update(){study=S.compare({route:q('ob-route').value,condition:q('ob-condition').value});budget=study.costs.total;q('ob-budget').value=budget;revision=1;render();}
    on('ob-route','change',update);on('ob-condition','change',update);on('ob-grant','change',()=>{grant=q('ob-grant').checked;render();});on('ob-budget','input',()=>{budget=Number(q('ob-budget').value);render();});on('ob-revoke','click',()=>{grant=false;q('ob-grant').checked=false;render();});on('ob-stale','click',()=>{revision++;phase=3;render();});on('ob-reset','click',()=>{q('ob-route').value='learned';q('ob-condition').value='valid';q('ob-grant').checked=false;grant=false;phase=1;update();});on('ob-glossary','click',()=>G.showGlossary());
    container.addEventListener('click',e=>{const b=e.target.closest('[data-ob-phase]');if(b){phase=Number(b.dataset.obPhase);render();}},{signal:abort.signal});render();
    return {dispose(){abort.abort();},snapshot(){return {study,phase,budget,grant,revision,current:S.atPhase(study,phase,{grant,budget,revision})};}};
  }
  window.OrchardLab.register({id:'changing-obligations',title:'07 · When the Obligations Change',version:'0.7.0',contractVersion:1,mount,run});
})();
